#!/usr/bin/env node
/**
 * PreToolUse (Edit|Write|MultiEdit): blocks edits that would break the project invariants.
 *  - Applied Flyway migrations are immutable (Flyway checksums would fail on every tenant schema).
 *    Add a new V<n>__description.sql instead.
 *  - Real .env files hold secrets; only .env.example is editable.
 *  - Lockfiles are generated by the package manager.
 * Exit code 2 = block the tool call and show the reason to Claude.
 */
import { execFileSync } from 'node:child_process';
import { readFileSync } from 'node:fs';
import path from 'node:path';

/** Accepts Windows (D:\x), POSIX and Git-Bash (/d/x) paths alike. */
function toNative(p) {
  if (process.platform === 'win32' && /^\/[a-zA-Z]\//.test(p)) p = `${p[1]}:${p.slice(2)}`;
  return path.resolve(p);
}

const input = JSON.parse(readFileSync(0, 'utf8') || '{}');
const filePath = input.tool_input?.file_path;
if (!filePath) process.exit(0);

const projectDir = toNative(process.env.CLAUDE_PROJECT_DIR ?? input.cwd ?? process.cwd());
const relative = path.relative(projectDir, toNative(filePath)).split(path.sep).join('/');
const base = path.basename(relative);

function block(reason) {
  process.stderr.write(`Blocked by .claude/hooks/guard-protected-files.mjs: ${reason}\n`);
  process.exit(2);
}

function isTracked(file) {
  try {
    execFileSync('git', ['ls-files', '--error-unmatch', file], { cwd: projectDir, stdio: 'pipe' });
    return true;
  } catch {
    return false;
  }
}

if (/\/db\/migration\/(public|tenant)\/V\d+__.+\.sql$/.test(relative) && isTracked(relative)) {
  block(`${relative} is an already committed Flyway migration. Never edit it; create the next V<n>__<description>.sql (see the flyway-migration skill).`);
}

if (/^\.env(\..+)?$/.test(base) && base !== '.env.example') {
  block(`${relative} contains secrets and is not editable by Claude. Update .env.example and ask the user to copy the values.`);
}

if (base === 'pnpm-lock.yaml' || base === 'package-lock.json') {
  block(`${relative} is generated. Run the package manager (pnpm add / pnpm install) instead of editing it.`);
}
